from engine import *

PART1 = "Part 1. Introduction"
PART2 = "Part 2. Getting started"

def blocks():
    b = []
    # ------------------------------------------------------------------ 1
    b += [H1(1, "About the Asset Knowledge Platform", ["Operator", "Engineer", "Reliability", "HSE", "Manager"], PART1,
             "The Asset Knowledge Platform joins the documents, drawings, work orders and lessons of the LLDPE unit into one searchable, source-checked knowledge base, and uses it to answer questions, support maintenance and prepare safe work."),
          H2("Purpose of this manual"),
          P("This manual explains how to use every part of the platform. It is written for the people who work with the LLDPE unit each day: operators, maintenance engineers, reliability engineers, HSE engineers and managers. Each chapter states who normally uses the feature, describes what the screen shows, and gives the steps to complete common tasks."),
          P("You do not need to read the manual from start to finish. Part 2 covers signing in and the screen layout. Parts 3 to 7 follow the sidebar of the application, so you can go directly to the chapter that matches the page you have open."),
          H2("The problem the platform addresses"),
          P("In a continuous process plant, the knowledge needed for a safe start-up, a quick repair or a correct decision is spread across many systems. Procedures sit in one place, drawings in another, work orders in a third, and the reasons behind a trip often exist only in the memory of senior staff. Engineers lose time searching, and they sometimes act on an outdated drawing or without knowing that the same fault happened before."),
          P("The platform brings these sources together and links each record to the equipment tag it concerns. Every answer shows where it came from, which revision of the document was used and whether that document is approved."),
          H2("What you can do with the platform"),
          TABLE(["Task", "Where in the platform", "Chapter"],
                [["See the state of all eight equipment sets", "Dashboard", "11"],
                 ["Find a drawing, datasheet, interlock or lesson for one machine", "Equipment Sets", "13"],
                 ["Ask a question in plain language and receive a cited answer", "AI Assistant", "32"],
                 ["Check what usually causes a fault and how it was fixed", "Failure Memory", "26"],
                 ["Review breakdown history and the forecast for the next 90 days", "Maintenance", "19 to 23"],
                 ["Plan maintenance work with permits and crew capacity", "Maintenance, Site plan", "25"],
                 ["Practise a one point lesson on a simulated machine", "OPL Library", "28, 29"],
                 ["Test how a release or a trip spreads across the plant", "Plot Plan, Scenarios", "30, 31"],
                 ["Add a new document or capture expert knowledge", "Knowledge Studio", "34"],
                 ["Produce a report for a meeting or an investigation", "Report Center", "37"]],
                [48, 32, 20]),
          NOTE("note", "The platform in this manual runs on sample data prepared for the CALIBER 2026 case. The equipment, documents and work orders are realistic, but they do not describe a real plant."),
          ]
    # ------------------------------------------------------------------ 2
    b += [H1(2, "How the platform is organised", ["Operator", "Engineer", "Reliability", "HSE", "Manager"], PART1,
             "Understanding how the pieces fit together makes every screen easier to read. This chapter describes the knowledge base, the three engines that use it and the way a record travels from a source document to an answer."),
          H2("The knowledge base"),
          P("All information is stored as small, labelled records called chunks. A chunk carries its text, the equipment tag it concerns, its revision and approval status, and the roles allowed to read it. Numbers such as set points are also stored as typed facts, and links between records, such as an interlock that protects a pump, are stored as relations."),
          TABLE(["Item", "Count in the sample data"],
                [["Searchable chunks", "1,109"], ["Typed facts", "447"], ["Relations between records", "624"], ["Documents", "98"], ["Work orders", "211"], ["One point lessons", "56"], ["Interlock documents", "8"], ["Instruments", "84"]],
                [60, 40]),
          H2("The three engines"),
          BUL(["**Answers.** The AI Assistant, global search and Equipment pages find the right record and show its source.",
               "**Reliability.** Failure Memory, Maintenance, Predictive maintenance and Performance study the work-order history and the lessons.",
               "**Safety and planning.** Interlocks, Live P&ID, start-up readiness, the OPL simulator, the hazard simulator and the Site plan prepare safe work."]),
          FLOW("f_overview", [[("box", "Source documents and records"), ("box", "Ingest and link on equipment tag"), ("box", "Check for conflicts"), ("dia", "Approved by a named person?", "No: stays a draft")],
                              [("db", "Knowledge base"), ("box", "Answers"), ("box", "Reliability"), ("pill", "Safety and planning")]],
               "How a record moves from a source document to the features that use it."),
          H2("Why the platform can be trusted"),
          P("Three rules apply everywhere in the platform. A record that is still a draft is clearly marked and is not used as an approved source. Every answer lists its sources. A figure in an answer is checked against the text of its source, and the confidence score drops when a figure cannot be found there."),
          ]
    # ------------------------------------------------------------------ 3
    b += [H1(3, "Equipment covered", ["Operator", "Engineer", "Reliability", "HSE", "Manager"], PART1,
             "The platform covers eight equipment sets of the LLDPE unit. Each set has its own P&ID, drawings, datasheet, interlock logic, lessons and maintenance history."),
          TABLE(["Tag", "Equipment", "Area", "Main interlock"],
                [["GA-1201A", "Feed/Charge Pump (hexane feed)", "1200 Feed preparation", "SEQ-1201"],
                 ["YD-2301", "Polymer Fluid Bed Dryer", "2300 Separation and drying", "SEQ-5500"],
                 ["DC-3401A", "Catalyst Reduction Reactor and heater", "3400", "SEQ-3401"],
                 ["KC-4501", "Recycle Gas Compressor", "4500 Gas recovery", "SEQ-4501"],
                 ["EA-5601", "Solvent Heater", "5600", "Control loop"],
                 ["LV-6701", "Separator Level Control", "6700", "SEQ-6701"],
                 ["CT-7801", "Cooling Tower Fan", "7800", "SEQ-7801"],
                 ["FA-8901", "Reflux Accumulator Drum", "8900", "SEQ-8901"]],
                [16, 38, 28, 18]),
          P("The set number used in the platform follows the order of this table: set 1 is GA-1201A and set 8 is FA-8901. The same tag appears on every page that concerns the equipment, which is how the platform links a work order to a drawing or a lesson."),
          FIG("p3_eqlist", "The Equipment Sets page lists all eight sets with their status.", maxh=120),
          ]
    # ------------------------------------------------------------------ 4
    b += [H1(4, "User roles and permissions", ["Operator", "Engineer", "Reliability", "HSE", "Manager"], PART1,
             "The platform has five roles. Your role is set when you sign in, and it decides which actions are available to you. The roles shown in this manual are the ones loaded in the application."),
          TABLE(["Action", "Operator", "Engineer", "Reliability", "HSE", "Manager"],
                [["Read approved knowledge, drawings and records", "Yes", "Yes", "Yes", "Yes", "Yes"],
                 ["Ask the AI Assistant and give feedback", "Yes", "Yes", "Yes", "Yes", "Yes"],
                 ["Submit a draft in Knowledge Studio", "Yes", "Yes", "Yes", "Yes", "Yes"],
                 ["Approve or reject knowledge items", "No", "Yes", "Yes", "Yes", "Yes"],
                 ["Delete knowledge items that are not your own drafts", "No", "Yes", "Yes", "No", "Yes"],
                 ["Accept scenario rules", "No", "Yes", "Yes", "No", "Yes"],
                 ["Import, bulk remove or generate records", "No", "No", "Yes", "No", "Yes"],
                 ["Open the administration settings", "No", "No", "No", "No", "Yes"]],
                [38, 12, 13, 15, 10, 12]),
          NOTE("note", "A person cannot approve an item that they wrote themselves, except in the Manager role. Another approver must review it. This rule is described in Chapter 40. When the platform builds answers and typed facts, the Operator role sees approved items only."),
          P("The sample installation contains 22 demonstration accounts: four managers, four operators, five engineers, five reliability engineers and four HSE engineers. The account named Caliber is the demonstration administrator and can switch between roles from the Settings panel to show how each role sees the platform."),
          ]
    # ------------------------------------------------------------------ 5
    b += [H1(5, "Before you start", ["Operator", "Engineer", "Reliability", "HSE", "Manager"], PART1,
             "This chapter lists what you need to open the platform and explains which parts of the sample installation are demonstrations."),
          H2("What you need"),
          BUL(["A current desktop browser such as Chrome, Edge or Firefox. A screen width of at least 1280 pixels shows the pages as they appear in this manual.",
               "A user name and password. The demonstration accounts are listed on the sign-in page.",
               "No installation. The platform runs in the browser."]),
          H2("What is a demonstration"),
          P("The sign-in page and the role list are for demonstration. The accounts are checked in the browser and are not a security control, so they must not be used to protect real plant information. The data is a sample prepared for the CALIBER 2026 case."),
          P("Features that connect to other systems, such as the engineering document system or the maintenance system, are shown with simulated connectors. Chapter 36 explains how they would be connected in a production installation."),
          H2("Conventions used in this manual"),
          TABLE(["Convention", "Meaning"],
                [["**Bold text**", "The name of a button, tab, field or menu item on the screen."],
                 ["Numbered orange circles", "A callout on a screenshot. The list below the figure explains each number."],
                 ["Numbered blue steps", "A procedure to carry out in order."],
                 ["Note, Tip, Caution boxes", "Extra information, a shortcut, or a warning about a possible mistake."],
                 ["Roles line", "The roles that normally use the feature described in the chapter."]],
                [34, 66]),
          ]
    # ------------------------------------------------------------------ 6
    b += [H1(6, "Signing in and out", ["Operator", "Engineer", "Reliability", "HSE", "Manager"], PART2,
             "Every session starts at the sign-in page. Your account decides your role, and your name is recorded on the items you create and approve."),
          H2("Sign in"),
          STEPS(["Open the platform in your browser. The sign-in page appears.",
                 "Type your **Username**, for example `Caliber`.",
                 "Type your **Password**. In the demonstration, the password is the first name followed by 2026, for example `Caliber2026`.",
                 "Select **Sign in**. The Dashboard opens."]),
          FIG("p2_login", "The sign-in page with the list of demonstration accounts open.",
              [(1, "Username field."), (2, "Password field."), (3, "**Sign in** button."), (4, "**Demo accounts** list. Select a row to fill in the user name."), (5, "Accounts with their name and role.")], maxh=140),
          NOTE("tip", "Select **Demo accounts**, then select a row. The user name and password are filled in for you."),
          H2("What happens when you sign in"),
          FLOW("f_signin", [[("pill", "Open the platform"), ("box", "Enter user name and password"), ("dia", "Credentials correct?", "No: wrong user name or password")],
                            [("box", "Role is set from the account"), ("box", "Pages and actions follow the role"), ("pill", "Dashboard opens")]],
               "The sign-in sequence."),
          H2("Sign out"),
          P("Your name and role appear at the bottom of the sidebar. Select the sign-out icon next to them to leave the session. The sign-in page appears again. Signing out and in is also the way to change to another account."),
          ]
    # ------------------------------------------------------------------ 7
    b += [H1(7, "The screen layout", ["Operator", "Engineer", "Reliability", "HSE", "Manager"], PART2,
             "All pages share the same layout: a sidebar on the left, a page area on the right and a few global controls. Learn this layout once and every page will look familiar."),
          FIG("p2_layout", "The layout of the platform, shown on the Dashboard.",
              [(1, "**Operate** group: daily pages for the plant."), (2, "Search box. Press `Ctrl+K` from any page."), (3, "**Knowledge** group: the assistant, Knowledge Studio, Failure Memory, Documents and OPL Library."), (4, "**Admin** group: reports, integrations, governance and data quality."), (5, "**Needs attention**: counts that need action today."), (6, "The page area. It changes with the page you select.")]),
          H2("The sidebar"),
          TABLE(["Group", "Pages"],
                [["Operate", "Dashboard, My work, Equipment Sets, Plot Plan, Maintenance, Performance, Scenarios, Interlock Library"],
                 ["Knowledge", "AI Assistant, Knowledge Studio, Failure Memory, Documents, OPL Library"],
                 ["Admin", "Report Center, Integrations, Governance, Data Quality"]],
                [20, 80]),
          P("At the bottom of the sidebar you see your name and role, the shared-database status (for example **Local only**) and the controls for notifications, the guided tour, settings and signing out. On a narrow screen the sidebar collapses behind a menu button."),
          H2("Page headers and tabs"),
          P("Each page starts with a title and a one-line description. Pages with several views, such as Maintenance or Knowledge Studio, show a row of tabs under the header. The selected tab is dark. Charts and tables are interactive: selecting a bar, a segment or a row usually filters the page or opens the related record."),
          ]
    # ------------------------------------------------------------------ 8
    b += [H1(8, "Global search", ["Operator", "Engineer", "Reliability", "HSE", "Manager"], PART2,
             "Global search looks through every approved document, work order, lesson and interlock at once and shows where each match comes from."),
          H2("Search from any page"),
          STEPS(["Press `Ctrl+K`, or select the search box at the top of the sidebar.",
                 "Type a word, a tag or a short phrase, for example `seal flush`.",
                 "Read the results. Each result shows its type (Lesson, Work order or Document), its title, its date, its status and a short extract.",
                 "Select a result to open the record."]),
          FIG("p2_search", "Global search results for the phrase seal flush.", maxh=130),
          NOTE("tip", "Search understands equipment tags and common word forms. A search for `PSLL-1201` finds the interlock initiator, and a search for `leaking` also finds records that say `leak`."),
          P("Results are ranked by how well they match, by the trust level of the source and by your role. Records that are still drafts are marked and rank lower than approved records."),
          ]
    # ------------------------------------------------------------------ 9
    b += [H1(9, "Notifications, settings and the guided tour", ["Operator", "Engineer", "Reliability", "HSE", "Manager"], PART2,
             "Three controls at the bottom of the sidebar help you stay informed and set up the platform: the notification bell, the settings panel and the guided tour."),
          H2("Notifications"),
          P("The bell shows a count when something needs attention. Select it to see the list. In the sample data it reports units above the forecast risk threshold and high-severity data issues that are still open. Items that wait for your approval also appear here."),
          FIG("p2_notif", "The notification list.", maxh=70),
          H2("Settings"),
          P("Select the gear icon to open the settings panel. The panel has four groups."),
          FIG("p2_settings", "The settings panel.",
              [(1, "Shared database and the **Sync now** button."), (2, "AI assistant options: use of the AI, answer style, answer language, connection test and diagnostics."), (3, "Report header printed at the top of every report."), (4, "Account: your name and role, the role selector for the demonstration administrator, the interface language and **Sign out**.")], maxh=170),
          BUL(["**Answer style.** Choose a concise or a detailed style for assistant answers.",
               "**Answer language.** Choose the language of answers. Bahasa Indonesia is available.",
               "**Interface language.** Choose English or Bahasa Indonesia for the screen text.",
               "**Run the demo walkthrough.** Starts the guided tour described below."]),
          H2("Guided tour"),
          P("The tour is a seven-step overview that highlights the main parts of the Dashboard. Select the question-mark icon in the sidebar footer to start it. Use **Next** to move on and **Skip tour** to leave."),
          FIG("p2_tour", "A step of the guided tour.", maxh=110),
          ]
    # ------------------------------------------------------------------ 10
    b += [H1(10, "Working offline and sharing data", ["Operator", "Engineer", "Reliability", "HSE", "Manager"], PART2,
             "The platform keeps its own copy of the knowledge base in your browser, so searching works without a connection. When a shared database is connected, changes made by one user are shared with the others."),
          H2("What is stored where"),
          TABLE(["Storage", "What it holds", "Who sees it"],
                [["Your browser", "A copy of the knowledge base, your drafts, your recent questions and your settings", "Only you, on this computer"],
                 ["Shared database", "Knowledge items, work orders, feedback, the audit trail and the question log", "All signed-in users, when connected"],
                 ["Production database (target)", "The same records in PostgreSQL with vector search", "All users of the Company installation"]],
                [24, 46, 30]),
          H2("Sync status"),
          P("The footer of the sidebar shows the sync status. **Local only** means that the shared database is not connected and your changes stay in this browser. When it is connected, the footer shows the time of the last sync, and the platform checks for changes every few seconds."),
          STEPS(["Open **Settings**.", "Read the **Shared database** panel. It states whether the platform is connected.", "Select **Sync now** to send your changes and receive the latest changes immediately."]),
          NOTE("caution", "If two people change the same item at nearly the same time, the platform keeps the newer change and marks the other as a conflict so that it can be reviewed."),
          H2("Offline search"),
          P("The label **Offline knowledge search** in the footer confirms that the search index is loaded in your browser. You can search, open documents and read lessons without a connection. Actions that need the shared database, such as syncing, wait until the connection returns."),
          ]
    return b
